#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include "cJSON.h"
#include "lodepng.h"

static std::string read_file(const char* path) {
    FILE* f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long n = ftell(f);
    fseek(f, 0, SEEK_SET);
    std::string s;
    s.resize(n);
    if (fread(&s[0], 1, n, f) != (size_t)n) { fclose(f); exit(1); }
    fclose(f);
    return s;
}

// Read a 2D matrix [rows][cols] from a cJSON array-of-arrays.
static std::vector<std::vector<double>> get_matrix(cJSON* root, const char* key) {
    cJSON* m = cJSON_GetObjectItemCaseSensitive(root, key);
    if (!m || !cJSON_IsArray(m)) { fprintf(stderr, "missing %s\n", key); exit(1); }
    std::vector<std::vector<double>> out;
    cJSON* row;
    cJSON_ArrayForEach(row, m) {
        std::vector<double> r;
        cJSON* v;
        cJSON_ArrayForEach(v, row) r.push_back(v->valuedouble);
        out.push_back(r);
    }
    return out;
}

static std::vector<double> get_vector(cJSON* root, const char* key) {
    cJSON* m = cJSON_GetObjectItemCaseSensitive(root, key);
    if (!m || !cJSON_IsArray(m)) { fprintf(stderr, "missing %s\n", key); exit(1); }
    std::vector<double> out;
    cJSON* v;
    cJSON_ArrayForEach(v, m) out.push_back(v->valuedouble);
    return out;
}

// y = W x + b, where W is [out][in].
static std::vector<double> linear(const std::vector<std::vector<double>>& W,
                                  const std::vector<double>& b,
                                  const std::vector<double>& x) {
    std::vector<double> y(W.size(), 0.0);
    for (size_t o = 0; o < W.size(); ++o) {
        double s = b[o];
        const std::vector<double>& row = W[o];
        for (size_t i = 0; i < row.size(); ++i) s += row[i] * x[i];
        y[o] = s;
    }
    return y;
}

static void relu(std::vector<double>& x) {
    for (double& v : x) if (v < 0) v = 0;
}

int main(int argc, char** argv) {
    if (argc < 3) {
        fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    // Load weights
    std::string wtext = read_file(argv[1]);
    cJSON* root = cJSON_Parse(wtext.c_str());
    if (!root) { fprintf(stderr, "bad json\n"); return 1; }

    auto W1 = get_matrix(root, "input_layer.weight");
    auto b1 = get_vector(root, "input_layer.bias");
    auto W2 = get_matrix(root, "hidden_layer.weight");
    auto b2 = get_vector(root, "hidden_layer.bias");
    auto W3 = get_matrix(root, "output_layer.weight");
    auto b3 = get_vector(root, "output_layer.bias");

    // Load image (decode to grayscale, 8-bit)
    std::vector<unsigned char> gray;
    unsigned width = 0, height = 0;
    unsigned err = lodepng::decode(gray, width, height, argv[2], LCT_GREY, 8);
    if (err) { fprintf(stderr, "png error %u: %s\n", err, lodepng_error_text(err)); return 1; }

    size_t n = (size_t)width * height;
    std::vector<double> x(n);
    for (size_t i = 0; i < n; ++i) x[i] = gray[i] / 255.0;

    if (x.size() != W1[0].size()) {
        fprintf(stderr, "image size %zu != model input %zu\n", x.size(), W1[0].size());
        return 1;
    }

    // Forward
    std::vector<double> h1 = linear(W1, b1, x); relu(h1);
    std::vector<double> h2 = linear(W2, b2, h1); relu(h2);
    std::vector<double> out = linear(W3, b3, h2);

    int best = 0;
    for (size_t i = 1; i < out.size(); ++i) if (out[i] > out[best]) best = (int)i;

    printf("%d\n", best);

    cJSON_Delete(root);
    return 0;
}
